<input type="hidden" name="id" value="<?= $this->h($tid) ?>"><input type="hidden" name="kind" value="<?= $kind ?>">
<?= $this->field('title',$kind==='topic'?'عنوان موضوع':'عنوان برچسب مسئله','text',$term['title']??'',true,160) ?>
