<?php if($kind==='topic'): ?><label>موضوع والد<select name="parent_id"><option value="">موضوع اصلی؛ بدون والد</option><?php foreach($rows as $parent):if($parent['kind']!=='topic'||$parent['id']===$tid){continue;} ?><option value="<?= $this->h($parent['id']) ?>" <?= ($term['parent_id']??'')===$parent['id']?'selected':'' ?>><?= $this->h($parent['path_title']??$parent['title']) ?><?= $parent['active']?'':' (غیرفعال)' ?></option><?php endforeach; ?></select></label>
<label>آیکون پیش‌فرض<select name="icon"><?php foreach(\Morshed\Product\Taxonomy::ICONS as $icon=>$label): ?><option value="<?= $icon ?>" <?= ($term['icon']??'book')===$icon?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label>
