<?php if(!empty($term['icon_asset_id'])): ?><label class="check"><input type="checkbox" name="remove_icon" value="1">حذف تصویر اختصاصی و استفاده از آیکون پیش‌فرض</label><?php endif; ?>
<?php else: ?><fieldset class="issue-picker" data-classification-picker><legend>زمینه‌های موضوعی این برچسب</legend><input type="hidden" name="related_topics_present" value="1"><label>جست‌وجوی موضوع<input type="search" data-classification-search></label><div data-selected-classifications class="selected-classifications"></div><div class="issue-options"><?php $linked=array_column(array_filter($issueLinks??[],fn($link)=>$link['issue_id']===$tid),'topic_id');foreach($rows as $topic):if($topic['kind']!=='topic'){continue;} ?><label><input type="checkbox" name="related_topics[]" value="<?= $this->h($topic['id']) ?>" <?= in_array($topic['id'],$linked,true)?'checked':'' ?>><span><?= $this->h($topic['path_title']??$topic['title']) ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
